from fastapi import FastAPI, Depends, Security, Request
from fastapi.security import SecurityScopes
from fastapi.testclient import TestClient

app = FastAPI()

def dep_a(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_b(security_scopes: SecurityScopes, a=Depends(dep_a)):
    return {"a": a, "scopes": security_scopes.scopes}

@app.get("/")
async def root(b=Security(dep_b, scopes=["route_scope"])):
    return b

client = TestClient(app)

def test_hierarchical_scopes():
    response = client.get("/")
    print(f"Response: {response.json()}")
    # Expected: {'a': ['route_scope'], 'scopes': ['route_scope']}
    # Current (buggy): {'a': [], 'scopes': ['route_scope']}
    assert response.json()["a"] == ["route_scope"]

if __name__ == "__main__":
    try:
        test_hierarchical_scopes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
EOF

